CREATE OR REPLACE FUNCTION public.plm_register_file(_revision uuid,_path text,_name text,_mime text,_size bigint,_hash text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.plm_revisions; fid uuid; receipt uuid; p jsonb; BEGIN SELECT * INTO r FROM public.plm_revisions WHERE id=_revision FOR UPDATE; IF NOT FOUND OR NOT public.plm_has_scope(r.organization_id,r.site_id) THEN RAISE EXCEPTION 'Unauthorized file scope'; END IF; IF r.state<>'DRAFT' OR (SELECT kind FROM public.plm_entities WHERE id=r.entity_id)<>'DOCUMENT' THEN RAISE EXCEPTION 'File attaches only to a draft document revision'; END IF; SELECT id INTO receipt FROM public.plm_file_verifications WHERE user_id=auth.uid() AND revision_id=_revision AND storage_path=_path AND original_name=_name AND mime_type=_mime AND size_bytes=_size AND sha256=_hash AND expires_at>now() AND used_at IS NULL FOR UPDATE; IF receipt IS NULL THEN RAISE EXCEPTION 'Server-verified file receipt required'; END IF; UPDATE public.plm_file_verifications SET used_at=now() WHERE id=receipt; INSERT INTO public.plm_document_files(revision_id,organization_id,site_id,storage_path,original_name,mime_type,size_bytes,sha256,uploaded_by) VALUES(_revision,r.organization_id,r.site_id,_path,_name,_mime,_size,_hash,auth.uid()) RETURNING id INTO fid; p:=r.payload||jsonb_build_object('fileSha256',_hash,'fileId',fid); UPDATE public.plm_revisions SET payload=p,content_hash=public.plm_content_hash(p),version=version+1,updated_at=now() WHERE id=r.id RETURNING * INTO r; INSERT INTO public.plm_audit_events(organization_id,site_id,actor_id,action,revision_id,reason,after_value,content_hash) VALUES(r.organization_id,r.site_id,auth.uid(),'REGISTER_FILE',r.id,'Server-verified immutable controlled file',jsonb_build_object('file_id',fid,'sha256',_hash,'size',_size),r.content_hash); RETURN fid; END $$;
CREATE FUNCTION public.plm_guard_file_and_operation_links() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE op jsonb; docid text; oldop jsonb; k text; BEGIN SELECT kind INTO k FROM public.plm_entities WHERE id=NEW.entity_id; IF EXISTS(SELECT 1 FROM public.plm_document_files f WHERE f.revision_id=NEW.id AND f.sha256 IS DISTINCT FROM NEW.payload->>'fileSha256') THEN RAISE EXCEPTION 'Verified document hash cannot be detached from its content'; END IF; IF k='ROUTING' THEN FOR op IN SELECT value FROM jsonb_array_elements(coalesce(NEW.payload->'operations','[]')) LOOP FOR docid IN SELECT value FROM jsonb_array_elements_text(coalesce(op->'documentRevisionIds','[]')) LOOP IF NOT EXISTS(SELECT 1 FROM public.plm_revisions r JOIN public.plm_entities e ON e.id=r.entity_id WHERE r.id=docid::uuid AND e.kind='DOCUMENT' AND r.organization_id=NEW.organization_id AND (r.site_id IS NULL OR r.site_id IS NOT DISTINCT FROM NEW.site_id)) THEN RAISE EXCEPTION 'Exact operation document revision outside scope'; END IF; END LOOP; END LOOP; IF TG_OP='UPDATE' THEN FOR oldop IN SELECT value FROM jsonb_array_elements(coalesce(OLD.payload->'operations','[]')) LOOP IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(NEW.payload->'operations','[]')) x WHERE x->>'id'=oldop->>'id') AND EXISTS(SELECT 1 FROM public.plm_revisions br CROSS JOIN LATERAL jsonb_array_elements(coalesce(br.payload->'lines','[]')) line WHERE br.organization_id=NEW.organization_id AND br.item_revision_id=NEW.item_revision_id AND line->>'operationId'=oldop->>'id') THEN RAISE EXCEPTION 'Operation is referenced by BOM materials; resolve references before removal'; END IF; END LOOP; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER plm_file_operation_links BEFORE INSERT OR UPDATE ON public.plm_revisions FOR EACH ROW EXECUTE FUNCTION public.plm_guard_file_and_operation_links();
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['items','boms','routings','changes','docs','syncs','work_orders','work_centers','inventory'] LOOP EXECUTE format('DROP POLICY IF EXISTS "Read %1$s" ON public.%1$I',t); EXECUTE format('CREATE POLICY "Unscoped legacy reference denied" ON public.%I FOR SELECT TO authenticated USING(false)',t); END LOOP; END $$;
DROP POLICY IF EXISTS "Read audit" ON public.audit;
CREATE POLICY plm_legacy_audit_denied ON public.audit FOR SELECT TO authenticated USING(false);